GUIDES = [
 {"slug":"membaca-hex-dan-rgb","sources":["css"],
  "id":{"title":"Membaca kode HEX dan kanal RGB","summary":"Pahami angka warna sebelum memilihnya untuk teks, latar, atau komponen.","sections":[("Tiga kanal dalam satu kode","Warna HEX enam digit menyimpan merah, hijau, dan biru sebagai tiga pasangan angka heksadesimal. #2C5A83 berarti merah 2C, hijau 5A, biru 83; setiap pasangan setara nilai 0 sampai 255. Bentuk tiga digit, seperti #ABC, menggandakan tiap digit menjadi #AABBCC."),("Bedakan kode dari tampilan","Kode yang sama dapat terlihat berbeda karena layar, kecerahan, pencahayaan, dan lingkungan sekitarnya. Untuk keputusan antarmuka, catat kode tepatnya, tetapi lihat juga contoh pada ukuran teks dan latar yang benar-benar akan dipakai."),("Simpan peran warna","Jangan hanya menamai warna sebagai biru atau hijau. Catat fungsinya, misalnya teks utama, latar, garis bidang, atau fokus. Peran ini membuat perubahan palet lebih mudah diperiksa.")],"example":"#2C5A83 sama dengan RGB (44, 90, 131). Kanal pertama 2C heksadesimal bernilai 44 desimal.","pitfall":"Dua warna yang tampak berbeda pada kartu besar belum tentu mudah dibaca sebagai teks kecil."},
  "en":{"title":"Read HEX codes and RGB channels","summary":"Understand the numbers before assigning colors to text, backgrounds or controls.","sections":[("Three channels in one code","A six-digit HEX color records red, green and blue as three hexadecimal pairs. #2C5A83 means red 2C, green 5A and blue 83; each pair corresponds to a value from 0 to 255. Three-digit notation such as #ABC doubles each digit to #AABBCC."),("Separate the code from its appearance","The same code may look different across displays, brightness settings, lighting and surrounding colors. For interface decisions, record the exact code and inspect a sample at the actual text size and background."),("Record color roles","Do not label a color only blue or green. Record its job, such as main text, surface, border or focus. Roles make later palette changes easier to review.")],"example":"#2C5A83 equals RGB (44, 90, 131). The first hexadecimal pair, 2C, equals decimal 44.","pitfall":"Two colors that differ on large swatches may still be hard to distinguish as small text."}},
 {"slug":"terang-relatif-dan-kontras","sources":["contrast"],
  "id":{"title":"Mengapa kecerahan relatif menentukan kontras","summary":"Rasio teks dan latar dihitung dari luminans relatif, bukan selisih angka HEX mentah.","sections":[("Ubah kanal sebelum menimbang","Dalam rumus WCAG, kanal sRGB dinormalisasi ke 0–1 lalu dilinearisasi. Nilai kanal kecil dibagi 12,92; nilai lain memakai pangkat 2,4. Luminans relatif menggabungkan hasil merah, hijau, dan biru dengan bobot masing-masing 0,2126, 0,7152, dan 0,0722."),("Bandingkan dua luminans","Rasio kontras adalah (luminans lebih terang + 0,05) dibagi (luminans lebih gelap + 0,05). Hitung dengan angka penuh; pembulatan hanya untuk tampilan. Urutan warna tidak mengubah rasio."),("Tinjau konteks nyata","Rasio matematis membantu menilai pasangan warna solid. Foto, gradien, transparansi, bayangan, dan lapisan di belakang teks menuntut pemeriksaan terhadap warna efektif di setiap bagian yang dilalui teks.")],"example":"Hitam #000000 pada putih #FFFFFF menghasilkan rasio 21:1. Membalik teks dan latar tetap 21:1.","pitfall":"Jangan mengurangi nilai kanal RGB lalu menganggap selisih itu rasio kontras WCAG."},
  "en":{"title":"Why relative luminance determines contrast","summary":"Text and background contrast uses relative luminance, not raw differences between HEX numbers.","sections":[("Transform channels before weighting","In the WCAG formula, sRGB channels are normalized to 0–1 and linearized. Small channel values are divided by 12.92; other values use a 2.4 power. Relative luminance combines linear red, green and blue with weights 0.2126, 0.7152 and 0.0722."),("Compare two luminances","Contrast ratio is (lighter luminance + 0.05) divided by (darker luminance + 0.05). Use full precision for the decision and round only the display. Reversing the colors does not change the ratio."),("Inspect real context","The mathematical ratio helps assess solid color pairs. Photos, gradients, transparency, shadows and layers behind text require checking the effective background wherever the text appears.")],"example":"Black #000000 on white #FFFFFF has a 21:1 ratio. Reversing text and background remains 21:1.","pitfall":"Do not subtract RGB channel values and call the difference a WCAG contrast ratio."}},
 {"slug":"ambang-teks-biasa-dan-besar","sources":["contrast"],
  "id":{"title":"Bedakan ambang untuk teks biasa dan teks besar","summary":"WCAG AA meminta rasio berbeda untuk ukuran teks berbeda; angka tampilan yang dibulatkan bukan dasar keputusan.","sections":[("Teks biasa","Untuk teks normal, kriteria kontras minimum tingkat AA adalah 4,5:1. Ukur pasangan warna teks dan latar yang benar-benar terlihat, termasuk keadaan tombol atau tautan. Rasio 4,49:1 tidak memenuhi ambang 4,5 walau dibulatkan menjadi 4,5."),("Teks besar","Untuk teks yang memenuhi definisi besar dalam WCAG, ambang AA adalah 3:1. Ukuran besar berkaitan dengan ukuran dan ketebalan huruf, bukan hanya nama kelas CSS. Bila ragu pada ukuran yang benar, gunakan ambang teks biasa sebagai pilihan desain yang lebih aman."),("Jangan menyamakan lulus dengan mudah","Rasio yang memenuhi angka minimum masih dapat terasa sulit pada font tipis, antialiasing, atau layar tertentu. Uji keterbacaan pada ukuran nyata serta keadaan hover, fokus, dan nonaktif yang relevan.")],"example":"Pasangan 4,7:1 memenuhi AA untuk teks biasa. Pasangan 3,4:1 dapat memenuhi AA untuk teks besar, tetapi tidak untuk teks biasa.","pitfall":"Jangan menyebut 4,49:1 lulus setelah angka dibulatkan menjadi satu desimal."},
  "en":{"title":"Distinguish normal and large text thresholds","summary":"WCAG AA has different thresholds for different text sizes; rounded display values do not decide a pass.","sections":[("Normal text","For normal text, WCAG AA minimum contrast is 4.5:1. Measure the actual foreground and background, including link or button states. A ratio of 4.49:1 does not meet 4.5 even if a display rounds it to 4.5."),("Large text","Text meeting WCAG's large-scale definition has a 3:1 AA threshold. Large-scale depends on size and weight, not a CSS class name alone. If the rendered size is uncertain, using the normal-text threshold is a safer design choice."),("Passing is not the whole experience","A ratio above the minimum may still feel difficult with thin fonts, antialiasing or particular screens. Inspect the actual size and relevant hover, focus and disabled states.")],"example":"A 4.7:1 pair meets AA for normal text. A 3.4:1 pair may meet AA for large text but not normal text.","pitfall":"Do not call 4.49:1 a pass after rounding the displayed number to one decimal."}},
 {"slug":"makna-tidak-hanya-warna","sources":["color"],
  "id":{"title":"Sampaikan makna tanpa mengandalkan warna saja","summary":"Tambahkan teks, bentuk, atau pola ketika warna menyampaikan status dan instruksi.","sections":[("Pikirkan informasi yang hilang","Merah dan hijau dapat membantu, tetapi sebagian pembaca tidak membedakannya dengan mudah. Bila formulir hanya mewarnai bidang salah merah, pesan kesalahan dan tindakan perbaikannya mungkin tidak terbaca bagi semua orang."),("Sediakan penanda kedua","Tulis pesan dekat bidang, beri ikon yang mempunyai label teks, atau gunakan pola dan angka pada grafik. Warna tetap boleh dipakai sebagai penguat; penanda kedua harus menyampaikan arti yang sama tanpa menebak palet."),("Uji tanpa warna","Lihat rancangan dalam skala abu-abu atau baca labelnya saja. Tanyakan apakah status, urutan, dan pilihan masih jelas. Pemeriksaan ini melengkapi, bukan menggantikan, pengujian kontras pasangan warna.")],"example":"Status ‘Tersimpan’ berwarna hijau tetap menampilkan teks ‘Tersimpan’ dan ikon centang berlabel; kesalahan menampilkan pesan yang menjelaskan bidangnya.","pitfall":"Legenda ‘merah = gagal, hijau = berhasil’ saja tetap bergantung pada perbedaan warna."},
  "en":{"title":"Communicate meaning without color alone","summary":"Add text, shape or pattern when color conveys a state or instruction.","sections":[("Find missing information","Red and green can help, but some readers cannot easily distinguish them. If a form only colors an invalid field red, the error and remedy may remain unclear."),("Provide a second cue","Write a message near the field, use an icon with a text label, or add patterns and numbers to a chart. Color may reinforce the message; the second cue must carry the same meaning without palette guesswork."),("Try a color-free check","View the design in grayscale or read its labels alone. Ask whether status, sequence and choices remain clear. This check complements, rather than replaces, measuring color-pair contrast.")],"example":"A green ‘Saved’ state still includes the text ‘Saved’ and a labelled check mark; an error explains which field needs attention.","pitfall":"A legend saying ‘red = fail, green = pass’ still relies on distinguishing colors."}},
 {"slug":"ikon-garis-dan-komponen","sources":["nontext","contrast"],
  "id":{"title":"Periksa batas input, ikon, dan grafik penting","summary":"Kontras nonteks memakai objek yang membawa informasi, bukan semua hiasan.","sections":[("Kenali petunjuk yang penting","Garis batas input mungkin diperlukan agar bidang dapat ditemukan. Tanda centang, ikon status, atau bagian grafik mungkin membawa informasi. Kriteria WCAG AA untuk informasi visual penting seperti ini biasanya meminta 3:1 terhadap warna yang bersebelahan."),("Uji warna yang bersentuhan","Periksa ikon terhadap latar di belakangnya serta garis kontrol terhadap bidang di sekitarnya. Kontras teks di dalam kontrol diperiksa terpisah dengan ambang teks. Garis sangat tipis dapat tampak lebih pucat di layar daripada hitungan warna solidnya."),("Pisahkan dekorasi","Bayangan atau ornamen yang tidak diperlukan untuk memahami maupun memakai antarmuka tidak otomatis menjadi target aturan yang sama. Catat alasan sebuah elemen dipakai agar pemeriksaan tidak berhenti pada satu skor seluruh halaman.")],"example":"Bidang input putih pada halaman putih membutuhkan batas yang terlihat jika batas itu satu-satunya petunjuk keberadaan bidang; teks labelnya tetap harus jelas.","pitfall":"Jangan menganggap rasio teks 4,5:1 membuktikan ikon status dan batas input juga terbaca."},
  "en":{"title":"Check input boundaries, icons and essential graphics","summary":"Non-text contrast concerns objects carrying information, rather than every decoration.","sections":[("Identify essential cues","An input border may be needed to find a field. A check mark, status icon or graph segment may carry meaning. WCAG AA generally calls for 3:1 against adjacent colors for such essential visual information."),("Test touching colors","Check an icon against its background and a control outline against surrounding surfaces. Text inside a control is checked separately against text thresholds. Very thin strokes can appear fainter on screen than a solid-color calculation suggests."),("Separate decoration","A shadow or ornament not required to understand or operate the interface does not automatically have the same requirement. Record why an element exists so review goes beyond a single page-wide score.")],"example":"A white input on a white page needs a visible border when that border is the only cue that the field exists; its label text still needs to be clear.","pitfall":"A 4.5:1 text ratio does not prove that status icons and input borders are visible."}},
 {"slug":"fokus-dan-keadaan-interaksi","sources":["focus","nontext","color"],
  "id":{"title":"Rancang keadaan fokus yang terlihat","summary":"Palet tidak selesai pada keadaan normal; navigasi keyboard harus tetap terlihat.","sections":[("Temukan setiap target keyboard","Gunakan Tab untuk berpindah melalui tautan, tombol, dan formulir. Fokus perlu terlihat pada setiap target yang dapat dioperasikan. Jangan menghapus outline bawaan tanpa mengganti dengan indikator yang jelas."),("Bandingkan dengan sekitar","Cincin fokus, garis bawah, atau bentuk lain harus tampak terhadap warna sekitarnya. Tinjau apakah perubahan hover dan fokus tetap berbeda ketika warna tidak dapat dibedakan. Label dan teks status membantu menjaga makna."),("Periksa urutan dan ukuran","Warna yang baik tidak memperbaiki urutan fokus yang membingungkan atau target yang sulit dicapai. Uji perjalanan keyboard dari awal hingga akhir serta tampilan di layar kecil sebelum menyatakan rancangan siap.")],"example":"Tombol gelap memakai cincin fokus terang yang jelas pada latar gelap dan tidak hilang ketika tombol juga sedang ditekan.","pitfall":"Jangan hanya merancang hover mouse; pengguna keyboard mungkin tidak pernah melihat petunjuk itu."},
  "en":{"title":"Design a visible keyboard focus state","summary":"A palette does not end at the default state; keyboard navigation must remain visible.","sections":[("Find every keyboard target","Use Tab to move through links, buttons and forms. Focus needs to be visible on each operable target. Do not remove the browser outline without replacing it with a clear indicator."),("Compare with surroundings","A focus ring, underline or other shape must stand out against adjacent colors. Check whether hover and focus remain distinguishable when hue is hard to perceive. Labels and state text help preserve meaning."),("Check order and size","Good color does not fix confusing focus order or hard-to-reach targets. Test the keyboard journey from start to finish and inspect small screens before calling a design ready.")],"example":"A dark button has a clear light focus ring on a dark surface; it remains visible while the button is pressed.","pitfall":"Do not design only for mouse hover; keyboard users may never see that cue."}},
 {"slug":"palet-berdasarkan-peran","sources":["contrast","color"],
  "id":{"title":"Susun palet menurut peran, bukan jumlah swatch","summary":"Tentukan latar, teks, garis, dan aksen lalu uji pasangan yang benar-benar bertemu.","sections":[("Mulai dari isi","Pilih warna untuk teks isi dan latar utama lebih dulu. Tambahkan latar sekunder, tombol, tautan, garis, dan status sesuai kebutuhan nyata. Tiap warna tambahan menciptakan pasangan yang harus diperiksa pada keadaan normal dan interaktif."),("Buat token yang jelas","Nama seperti text-primary, surface-muted, dan border-input lebih tahan perubahan daripada blue-500 ketika warna berganti. Simpan pasangan yang disetujui bersama nilai HEX, peran, dan rasio aktual."),("Hindari klaim harmoni otomatis","Alat variasi warna situs ini mencampur kanal sRGB dengan putih atau hitam untuk menghasilkan lima kandidat. Itu operasi aritmetika, bukan penilaian estetika atau kelulusan aksesibilitas. Uji tiap kandidat pada peran serta latarnya.")],"example":"Palet kecil dapat memakai satu latar utama, satu teks utama, satu aksen tombol, dan satu warna fokus; catat kontras teks-latar dan tombol-teks secara terpisah.","pitfall":"Lima swatch yang terlihat serasi tidak otomatis memberi label, batas, dan fokus yang terbaca."},
  "en":{"title":"Build palettes by role, not swatch count","summary":"Choose surfaces, text, borders and accents, then test the actual touching pairs.","sections":[("Start with content","Choose body text and the main background first. Add secondary surface, button, link, border and state colors only for real needs. Each extra color creates pairs to review in default and interactive states."),("Name clear tokens","Names such as text-primary, surface-muted and border-input age better than blue-500 when a hue changes. Keep approved pairs with their HEX values, roles and actual contrast ratios."),("Avoid automatic harmony claims","This site's variation tool mixes sRGB channels with white or black to offer five candidates. It is arithmetic, not an aesthetic judgement or accessibility pass. Test each candidate in its role and against its background.")],"example":"A compact palette might use one main surface, one body text color, one button accent and one focus color; record text-on-surface and button-label ratios separately.","pitfall":"Five attractive swatches do not automatically make labels, borders and focus visible."}},
 {"slug":"lembar-uji-warna","sources":["contrast","nontext","color","focus"],
  "id":{"title":"Buat lembar uji warna sebelum terbit","summary":"Catat pasangan warna, fungsi, hasil hitung, dan pemeriksaan visual dalam satu tempat.","sections":[("Inventaris pasangan","Daftarkan teks isi dan latarnya, tautan, label tombol, pesan kesalahan, garis input, ikon penting, serta fokus. Simpan HEX dan ukuran teks yang sesungguhnya. Jangan hanya menguji dua warna merek."),("Hitung lalu lihat","Gunakan pemeriksa kontras untuk pasangan solid. Catat rasio tanpa membulatkan saat mengambil keputusan; sesudah itu lihat rancangan pada ukuran nyata, layar kecil, zoom, dan kondisi terang berbeda. Untuk foto atau gradien, uji bagian latar di bawah setiap teks."),("Simpan keputusan dan revisi","Tuliskan pasangan yang gagal, perbaikan yang dipilih, serta tanggalnya. Uji ulang setelah mengubah warna, ukuran teks, ketebalan garis, atau latar. Lembar kecil yang dapat diulang lebih berguna daripada skor tunggal tanpa konteks.")],"example":"Baris catatan: teks isi #1E293B pada latar #FFFFFF, ukuran 16 px, rasio dari alat, hasil pemeriksaan visual, tanggal, dan tindakan bila perlu.","pitfall":"Jangan mengklaim seluruh halaman memenuhi WCAG hanya karena satu pasangan warna lulus alat."},
  "en":{"title":"Make a color review sheet before publishing","summary":"Record each color pair, its purpose, calculated result and visual review in one place.","sections":[("Inventory real pairs","List body text and surface, links, button labels, error messages, input boundaries, meaningful icons and focus indicators. Keep HEX values and actual rendered text size. Do not test only two brand colors."),("Calculate, then inspect","Use the contrast checker for solid pairs. Decide with the unrounded ratio; then inspect the design at actual size, on small screens, at zoom and in different lighting. For photos or gradients, sample the background under every part of the text."),("Keep decisions and revisions","Write down failing pairs, the chosen fix and the date. Recheck after changing color, text size, stroke weight or background. A short repeatable sheet is more useful than one score without context.")],"example":"Sample row: body text #1E293B on #FFFFFF, 16 px, ratio from the tool, visual check result, date and action if needed.","pitfall":"Do not claim a whole page meets WCAG because one color pair passes the tool."}},
]
